// Message body: { key: string, width: number, format?: string }
export default {
  async fetch(request, env) {
    if (request.method !== "POST") return new Response("Method Not Allowed", { status: 405 });
    const job = await request.json();
    if (typeof job?.key !== "string" || !Number.isInteger(job?.width)) {
      return new Response("Expected { key, width }", { status: 400 });
    }
    await env.JOBS.send(job);
    return new Response("Queued", { status: 202 });
  },

  async queue(batch, env) {
    for (const msg of batch.messages) {
      const { key, width, format = "image/webp" } = msg.body;
      try {
        const src = await env.IMAGES_BUCKET.get(key);
        if (!src) {
          console.error(JSON.stringify({ msg: "source missing", key }));
          msg.ack();
          continue;
        }
        const out = await env.IMAGES.input(src.body).transform({ width }).output({ format });
        const res = out.response();
        await env.IMAGES_BUCKET.put(`resized/${width}/${key}`, res.body, {
          httpMetadata: { contentType: out.contentType() },
        });
        msg.ack();
      } catch (err) {
        console.error(JSON.stringify({ msg: "resize failed", key, attempts: msg.attempts, error: String(err) }));
        msg.retry({ delaySeconds: Math.min(30 * 2 ** (msg.attempts - 1), 600) });
      }
    }
  },
};

